-- Replaces ad-hoc dummy data with a realistic, deterministic demo dataset.
-- Keeps any existing admin account(s) so local credentials configured via environment still work.

DELETE FROM meal_plan_recipes;
DELETE FROM meal_plans;
DELETE FROM reviews;
DELETE FROM recipe_ingredients;
DELETE FROM recipe_categories;
DELETE FROM recipes;

WITH non_admin_users AS (
    SELECT u.user_id
    FROM users u
    WHERE NOT EXISTS (
        SELECT 1
        FROM user_roles ur
        WHERE ur.user_id = u.user_id
          AND ur.roles = 'ADMIN'
    )
)
DELETE FROM user_roles ur
USING non_admin_users nau
WHERE ur.user_id = nau.user_id;

WITH non_admin_users AS (
    SELECT u.user_id
    FROM users u
    WHERE NOT EXISTS (
        SELECT 1
        FROM user_roles ur
        WHERE ur.user_id = u.user_id
          AND ur.roles = 'ADMIN'
    )
)
DELETE FROM users u
USING non_admin_users nau
WHERE u.user_id = nau.user_id;

ON CONFLICT (category_id) DO UPDATE
SET category_type = EXCLUDED.category_type,
    updated_at = EXCLUDED.updated_at;

ON CONFLICT (ingredient_id) DO UPDATE
SET name = EXCLUDED.name,
    unit_hint = EXCLUDED.unit_hint,
    updated_at = EXCLUDED.updated_at;






