    ('20000000-0000-0000-0000-000000000001', TIMESTAMP '2026-03-01 18:20:00', TIMESTAMP '2026-03-22 19:10:00', 'Creamy Mushroom Pasta', 'A cozy weeknight pasta with sauteed mushrooms, garlic and a light cream sauce finished with fresh basil.', 35, 'MEDIUM', 4.5, 'https://images.example.com/recipes/creamy-mushroom-pasta.jpg', 640, '10000000-0000-0000-0000-000000000002'),
    ('20000000-0000-0000-0000-000000000002', TIMESTAMP '2026-03-02 12:15:00', TIMESTAMP '2026-03-23 18:30:00', 'Teriyaki Chicken Rice Bowl', 'Tender chicken breast glazed with soy, garlic and ginger, served over rice with broccoli and carrots.', 30, 'MEDIUM', 4.5, 'https://images.example.com/recipes/teriyaki-chicken-rice-bowl.jpg', 620, '10000000-0000-0000-0000-000000000004'),
    ('20000000-0000-0000-0000-000000000003', TIMESTAMP '2026-03-03 17:05:00', TIMESTAMP '2026-03-24 11:45:00', 'Tofu Veggie Stir-Fry', 'Crisp broccoli, peppers and carrots tossed with golden tofu and a savory soy-ginger sauce.', 25, 'EASY', 4.333333333333333, 'https://images.example.com/recipes/tofu-veggie-stir-fry.jpg', 480, '10000000-0000-0000-0000-000000000005'),
    ('20000000-0000-0000-0000-000000000004', TIMESTAMP '2026-03-04 18:45:00', TIMESTAMP '2026-03-24 20:00:00', 'Coconut Tofu Curry', 'A creamy tofu curry with spinach, warm spices and coconut milk that reheats beautifully for lunches.', 35, 'MEDIUM', 5.0, 'https://images.example.com/recipes/coconut-tofu-curry.jpg', 560, '10000000-0000-0000-0000-000000000003'),
    ('20000000-0000-0000-0000-000000000005', TIMESTAMP '2026-03-05 19:30:00', TIMESTAMP '2026-03-25 13:25:00', 'Romanian Pork Potato Tray Bake', 'Roasted pork, potatoes and onions seasoned with paprika and garlic for a hearty family-style dinner.', 75, 'MEDIUM', 4.5, 'https://images.example.com/recipes/romanian-pork-potato-tray-bake.jpg', 710, '10000000-0000-0000-0000-000000000006'),
    ('20000000-0000-0000-0000-000000000006', TIMESTAMP '2026-03-06 18:00:00', TIMESTAMP '2026-03-25 21:10:00', 'Garlic Shrimp Pasta', 'Shrimp, lemon and chili flakes make this quick pasta bright enough for a Friday dinner without much prep.', 20, 'EASY', 4.333333333333333, 'https://images.example.com/recipes/garlic-shrimp-pasta.jpg', 590, '10000000-0000-0000-0000-000000000002'),
    ('20000000-0000-0000-0000-000000000007', TIMESTAMP '2026-03-07 09:10:00', TIMESTAMP '2026-03-26 08:50:00', 'Spinach Mushroom Omelette Toast', 'A protein-rich breakfast with buttery toast, sauteed mushrooms and a soft omelette folded with spinach.', 15, 'EASY', 4.5, 'https://images.example.com/recipes/spinach-mushroom-omelette-toast.jpg', 420, '10000000-0000-0000-0000-000000000001'),
    ('20000000-0000-0000-0000-000000000008', TIMESTAMP '2026-03-08 17:20:00', TIMESTAMP '2026-03-26 19:35:00', 'Beef and Broccoli Rice Skillet', 'Thin-sliced beef and broccoli cooked in a soy-garlic sauce and spooned over warm rice.', 25, 'MEDIUM', 4.5, 'https://images.example.com/recipes/beef-and-broccoli-rice-skillet.jpg', 610, '10000000-0000-0000-0000-000000000003'),
    ('20000000-0000-0000-0000-000000000009', TIMESTAMP '2026-03-09 07:40:00', TIMESTAMP '2026-03-26 09:00:00', 'Avocado Egg Toast', 'Mashed avocado, jammy eggs and a squeeze of lemon on toasted bread for a fast weekday breakfast.', 10, 'EASY', 4.5, 'https://images.example.com/recipes/avocado-egg-toast.jpg', 350, '10000000-0000-0000-0000-000000000001'),
