INSERT INTO reviews (review_id, created_at, updated_at, rating, text, user_id, recipe_id)
VALUES
    ('30000000-0000-0000-0000-000000000001', TIMESTAMP '2026-03-20 18:00:00', TIMESTAMP '2026-03-20 18:00:00', 5, 'Really comforting and the basil keeps it from feeling too heavy.', '10000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000001'),
    ('30000000-0000-0000-0000-000000000002', TIMESTAMP '2026-03-21 12:30:00', TIMESTAMP '2026-03-21 12:30:00', 4, 'Good flavor and easy to scale up for leftovers.', '10000000-0000-0000-0000-000000000003', '20000000-0000-0000-0000-000000000001'),
    ('30000000-0000-0000-0000-000000000003', TIMESTAMP '2026-03-20 19:10:00', TIMESTAMP '2026-03-20 19:10:00', 5, 'The soy and ginger balance was spot on for a fast dinner bowl.', '10000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002'),
    ('30000000-0000-0000-0000-000000000004', TIMESTAMP '2026-03-22 08:05:00', TIMESTAMP '2026-03-22 08:05:00', 4, 'Great meal prep lunch; I added extra broccoli and it still worked well.', '10000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000002'),
    ('30000000-0000-0000-0000-000000000005', TIMESTAMP '2026-03-21 18:40:00', TIMESTAMP '2026-03-21 18:40:00', 5, 'Crisp vegetables and tofu with just enough sauce.', '10000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000003'),
    ('30000000-0000-0000-0000-000000000006', TIMESTAMP '2026-03-22 11:15:00', TIMESTAMP '2026-03-22 11:15:00', 4, 'Very dependable weeknight stir-fry and the rice made it filling.', '10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000003'),
    ('30000000-0000-0000-0000-000000000007', TIMESTAMP '2026-03-23 13:00:00', TIMESTAMP '2026-03-23 13:00:00', 4, 'Simple ingredients but the ginger and soy make it taste fresh.', '10000000-0000-0000-0000-000000000006', '20000000-0000-0000-0000-000000000003'),
    ('30000000-0000-0000-0000-000000000008', TIMESTAMP '2026-03-22 19:45:00', TIMESTAMP '2026-03-22 19:45:00', 5, 'Rich without being too heavy and perfect for reheating the next day.', '10000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000004'),
    ('30000000-0000-0000-0000-000000000009', TIMESTAMP '2026-03-23 09:50:00', TIMESTAMP '2026-03-23 09:50:00', 5, 'One of the better tofu curries I have tried for lunch prep.', '10000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000004'),
    ('30000000-0000-0000-0000-000000000010', TIMESTAMP '2026-03-22 18:10:00', TIMESTAMP '2026-03-22 18:10:00', 4, 'Classic tray bake comfort food and the potatoes crisp nicely.', '10000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000005'),
    ('30000000-0000-0000-0000-000000000011', TIMESTAMP '2026-03-24 08:25:00', TIMESTAMP '2026-03-24 08:25:00', 5, 'Very hearty and the garlic-paprika seasoning is excellent.', '10000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000005'),
    ('30000000-0000-0000-0000-000000000012', TIMESTAMP '2026-03-23 19:20:00', TIMESTAMP '2026-03-23 19:20:00', 5, 'Fast, bright and exactly the kind of pasta I would make on a Friday.', '10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000006'),
    ('30000000-0000-0000-0000-000000000013', TIMESTAMP '2026-03-24 12:05:00', TIMESTAMP '2026-03-24 12:05:00', 4, 'Good balance of lemon and chili. I would make it again.', '10000000-0000-0000-0000-000000000003', '20000000-0000-0000-0000-000000000006'),
    ('30000000-0000-0000-0000-000000000014', TIMESTAMP '2026-03-24 18:35:00', TIMESTAMP '2026-03-24 18:35:00', 4, 'Quick enough for a weeknight but still tastes like a treat.', '10000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000006'),
    ('30000000-0000-0000-0000-000000000015', TIMESTAMP '2026-03-24 07:50:00', TIMESTAMP '2026-03-24 07:50:00', 4, 'Solid breakfast recipe and the mushrooms add a lot of flavor.', '10000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000007'),
    ('30000000-0000-0000-0000-000000000016', TIMESTAMP '2026-03-25 09:10:00', TIMESTAMP '2026-03-25 09:10:00', 5, 'Easy breakfast-for-dinner option when the fridge is nearly empty.', '10000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000007'),
    ('30000000-0000-0000-0000-000000000017', TIMESTAMP '2026-03-24 19:00:00', TIMESTAMP '2026-03-24 19:00:00', 4, 'Tastes like takeout but uses straightforward ingredients.', '10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000008'),
    ('30000000-0000-0000-0000-000000000018', TIMESTAMP '2026-03-25 12:20:00', TIMESTAMP '2026-03-25 12:20:00', 5, 'The beef stays tender and it comes together surprisingly fast.', '10000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000008'),
    ('30000000-0000-0000-0000-000000000019', TIMESTAMP '2026-03-25 07:30:00', TIMESTAMP '2026-03-25 07:30:00', 4, 'Fast breakfast and the lemon keeps the avocado bright.', '10000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000009'),
    ('30000000-0000-0000-0000-000000000020', TIMESTAMP '2026-03-26 08:00:00', TIMESTAMP '2026-03-26 08:00:00', 5, 'Simple but satisfying, especially with the soft eggs.', '10000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000009');
